// Secure code: Using java.util.Scanner with input validation and sanitization
import java.util.Scanner;

public class SecureExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a command: ");
        String userInput = scanner.nextLine(); // validated and sanitized input

        // Validate input to only allow specific commands
        if (userInput == null || userInput.trim().isEmpty()) {
            System.out.println("Invalid input.");
            return;
        }

        // Sanitize input by removing any special characters or whitespace
        userInput = userInput.replaceAll("[^a-zA-Z0-9\\s]", "");

        // Only allow specific commands for safety
        String[] allowedCommands = {"ls", "pwd", "whoami"};
        boolean isAllowed = false;
        for (String cmd : allowedCommands) {
            if (userInput.trim().equalsIgnoreCase(cmd)) {
                isAllowed = true;
                break;
            }
        }

        if (!isAllowed) {
            System.out.println("Command not allowed.");
            return;
        }

        try {
            Process process = Runtime.getRuntime().exec(userInput);
            int exitCode = process.waitFor();
            System.out.println("Command executed with exit code: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

